styles:
:root{--bg:#070707;--bg2:#0e0e0e;--paper:#f2f0eb;--paper2:#e7e4de;--ink:#0a0a0a;--text:#f4f2ee;--muted:#a6a29b;--red:#e81848;--line:rgba(255,255,255,.15);--lineD:rgba(10,10,10,.16);--max:1480px;--pad:clamp(20px,3.35vw,58px);--ease:cubic-bezier(.16,1,.3,1);--display:"Helvetica Neue",Helvetica,Arial,sans-serif}
*{box-sizing:border-box}html{scroll-behavior:smooth;background:var(--bg)}body{margin:0;background:var(--bg);color:var(--text);font-family:var(--display);font-size:16px;line-height:1.5;overflow-x:hidden}body.menu-open{overflow:hidden}a{color:inherit;text-decoration:none}button{font:inherit}img{display:block;width:100%;height:auto}figure{margin:0}.shell{width:min(var(--max),100%);margin-inline:auto;padding-inline:var(--pad)}
.skip{position:fixed;left:12px;top:12px;z-index:200;background:var(--paper);color:var(--ink);padding:10px 14px;transform:translateY(-140%);transition:.2s}.skip:focus{transform:none}.nav{height:82px;position:fixed;z-index:90;top:0;left:0;right:0;display:grid;grid-template-columns:auto 1fr auto;align-items:center;padding:0 var(--pad);background:rgba(7,7,7,.8);backdrop-filter:blur(16px);border-bottom:1px solid rgba(255,255,255,.08)}.brand{display:flex;align-items:center;gap:10px;font-weight:700;letter-spacing:-.04em;font-size:18px}.brand-mark{width:29px;height:29px;object-fit:contain}.nav-links{justify-self:end;display:flex;align-items:center;gap:clamp(18px,2vw,34px);font-size:13px}.nav-links a{color:#d8d5d0;transition:color .2s}.nav-links a:hover,.nav-links a:focus-visible,.nav-links a[aria-current=page]{color:#fff}.nav-cta{border:1px solid rgba(255,255,255,.26);padding:11px 16px;transition:background .25s var(--ease),color .25s var(--ease)!important}.nav-cta:hover{background:#fff;color:#0a0a0a!important}.menu-btn{display:none;width:46px;height:46px;background:none;border:1px solid rgba(255,255,255,.2);color:white;align-items:center;justify-content:center;cursor:pointer;position:relative}.menu-btn span,.menu-btn:before{content:"";display:block;width:18px;height:1px;background:currentColor;position:absolute}.menu-btn span{transform:translateY(4px)}.menu-btn:before{transform:translateY(-4px)}.mobile-menu{display:none;position:fixed;inset:82px 0 0;z-index:80;background:#070707;padding:32px var(--pad) 40px}.mobile-menu a{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding:18px 0;font-size:clamp(28px,7vw,42px);letter-spacing:-.04em}
.kicker{font-size:11px;text-transform:uppercase;letter-spacing:.19em;color:var(--muted)}.btn{display:inline-flex;min-height:48px;align-items:center;justify-content:center;gap:10px;padding:13px 19px;border:1px solid rgba(255,255,255,.25);font-size:13px;transition:transform .25s var(--ease),background .25s var(--ease),border-color .25s var(--ease)}.btn.primary{background:var(--red);border-color:var(--red)}.btn:hover{transform:translateY(-2px);border-color:#fff}.btn.primary:hover{background:#f12557}.text-link{font-size:13px;border-bottom:1px solid currentColor;padding:11px 0;min-height:44px;display:inline-flex;gap:12px;align-items:center}
/* Hero */
.hero{height:178svh;position:relative;overflow:clip;--hero-progress:0}.hero-stage{position:sticky;top:0;height:100svh;padding-top:82px;display:flex;align-items:flex-end;overflow:hidden;background:#070707}.hero-stage:before{content:"";position:absolute;inset:82px 0 auto;height:1px;background:linear-gradient(90deg,transparent 0 4%,rgba(255,255,255,.11) 4% 96%,transparent 96%)}.hero .shell{padding-top:clamp(58px,6.5vw,104px);padding-bottom:clamp(34px,4vw,58px)}.hero-meta{display:flex;justify-content:space-between;align-items:center;padding-bottom:22px;border-bottom:1px solid var(--line);margin-bottom:clamp(24px,3.2vw,42px)}.hero-meta span:last-child{font-size:12px;color:#87837d}.hero-grid{display:grid;grid-template-columns:1.22fr .78fr;gap:clamp(34px,6vw,110px);align-items:end}.hero h1{font-size:clamp(64px,8.25vw,132px);line-height:.85;letter-spacing:-.071em;font-weight:550;margin:0;max-width:950px;transform:translate3d(0,calc(var(--hero-progress) * -10px),0);will-change:transform}.hero h1 em{font-style:normal;color:var(--text);position:relative;display:inline}.hero h1 em:after{content:"";position:absolute;left:.035em;bottom:-.12em;width:clamp(44px,5vw,78px);height:clamp(5px,.48vw,8px);background:var(--red);transform-origin:left center;transform:scaleX(calc(.58 + var(--hero-progress) * .42))}.hero-side{padding-bottom:.35em;transform:translate3d(0,calc(var(--hero-progress) * -5px),0);will-change:transform}.hero-lead{font-size:clamp(18px,1.45vw,23px);line-height:1.4;color:#c7c3bc;margin:0 0 28px;max-width:580px;letter-spacing:-.02em}.hero-actions{display:flex;align-items:center;gap:18px;flex-wrap:wrap}
.search-sequence{margin-top:clamp(38px,4.4vw,64px);border-top:1px solid var(--line);border-bottom:1px solid var(--line);position:relative;padding:0 0 18px}.sequence-head{height:48px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);font-size:10px;text-transform:uppercase;letter-spacing:.16em;color:#8f8b84}.sequence-words{display:grid;grid-template-columns:1.15fr .92fr 1.18fr .75fr;align-items:end;min-height:126px}.signal-word{position:relative;display:flex;align-items:flex-end;gap:12px;padding:24px 24px 20px 0;color:#6f6b65;transition:color .35s var(--ease),transform .45s var(--ease)}.signal-word:not(:first-child){padding-left:22px}.signal-word b{font-size:10px;font-weight:500;letter-spacing:.14em;color:#68645f;transform:translateY(-5px);transition:color .35s var(--ease)}.signal-word span{font-size:clamp(25px,2.5vw,40px);letter-spacing:-.045em;line-height:1;font-weight:500}.signal-word.active{color:#fff;transform:translateY(-2px)}.signal-word.active b{color:var(--red)}.sequence-rail{height:1px;background:rgba(255,255,255,.15);position:relative;overflow:hidden}.sequence-rail i{display:block;height:100%;width:calc(var(--hero-progress) * 100%);background:var(--red);transition:width .06s linear}.sequence-end{display:flex;justify-content:space-between;align-items:center;gap:24px;padding-top:15px;color:#77736d;transition:color .45s var(--ease)}.sequence-end span{font-size:9px;text-transform:uppercase;letter-spacing:.16em}.sequence-end strong{font-size:13px;font-weight:450;letter-spacing:-.015em}.hero.is-complete .sequence-end{color:#d8d4ce}.hero.is-complete .sequence-end strong{color:#fff}.hero-endpoint{position:absolute;right:var(--pad);bottom:22px;font-size:9px;text-transform:uppercase;letter-spacing:.16em;color:#5e5a55;opacity:0;transform:translateY(8px);transition:opacity .45s var(--ease),transform .45s var(--ease)}.hero.is-complete .hero-endpoint{opacity:1;transform:none}
/* Manifesto */
.manifesto{background:var(--paper);color:var(--ink);padding:clamp(105px,11vw,180px) 0;position:relative;overflow:hidden}.manifesto-grid{display:grid;grid-template-columns:.36fr 1.64fr;gap:clamp(38px,7vw,118px)}.manifesto h2{font-size:clamp(52px,7.2vw,112px);line-height:.89;letter-spacing:-.066em;font-weight:540;margin:0;max-width:1080px}.manifesto h2 .red{color:var(--red)}.manifesto-copy{display:grid;grid-template-columns:1fr 1fr;gap:36px;margin-top:clamp(44px,5vw,78px);max-width:930px}.manifesto-copy p{margin:0;font-size:clamp(17px,1.25vw,21px);line-height:1.52;color:#45423d}.understand-flow{margin-top:clamp(74px,8vw,124px);border-top:1px solid var(--lineD);display:grid;grid-template-columns:1fr 1fr 1fr 1fr}.flow-cell{padding:22px 18px 28px 0;border-right:1px solid var(--lineD);min-height:180px;display:flex;flex-direction:column;justify-content:space-between}.flow-cell:not(:first-child){padding-left:20px}.flow-cell:last-child{border-right:0}.flow-cell span{font-size:10px;text-transform:uppercase;letter-spacing:.15em;color:#77726b}.flow-cell strong{font-size:clamp(25px,2.25vw,37px);font-weight:500;letter-spacing:-.045em}.flow-cell:nth-child(4) strong{color:var(--red)}
/* why */
.why{background:var(--paper);color:var(--ink);padding:0 0 clamp(110px,12vw,190px)}.why-grid{display:grid;grid-template-columns:1.04fr .96fr;gap:clamp(40px,7vw,116px);border-top:1px solid var(--lineD);padding-top:clamp(58px,6vw,92px);align-items:start}.why-media{position:sticky;top:112px;overflow:hidden;background:#bbb;aspect-ratio:1.18/1}.why-media img{width:100%;height:108%;object-fit:cover;object-position:50% 52%;transform:translateY(var(--why-img-y,0px)) scale(1.035);will-change:transform}.why-copy .kicker{color:#6f6a63}.why h2{font-size:clamp(42px,5.1vw,79px);line-height:.94;letter-spacing:-.057em;font-weight:540;margin:22px 0 38px}.why-intro{font-size:clamp(18px,1.35vw,22px);line-height:1.5;color:#46423c;max-width:650px}.why-points{margin-top:52px;border-top:1px solid var(--lineD)}.why-point{display:grid;grid-template-columns:54px 1fr;gap:22px;padding:26px 0;border-bottom:1px solid var(--lineD)}.why-point span{font-size:11px;color:#77726b}.why-point strong{font-size:clamp(24px,2vw,34px);font-weight:500;letter-spacing:-.04em}.why-point p{grid-column:2;margin:0;color:#5a5650;max-width:590px}
/* Architecture signature — editorial website blueprint */
.architecture{background:#0a0a0a;color:#fff;padding:clamp(110px,11vw,178px) 0;position:relative;overflow:clip}.arch-head{display:grid;grid-template-columns:.36fr 1.64fr;gap:clamp(38px,7vw,118px);margin-bottom:clamp(70px,8vw,120px)}.arch-head h2{font-size:clamp(48px,6vw,94px);line-height:.91;letter-spacing:-.063em;font-weight:530;margin:0;max-width:990px}.arch-head p{max-width:680px;color:#aaa59e;font-size:clamp(17px,1.3vw,21px);margin:34px 0 0}.arch-story{position:relative}.arch-sticky-pair{position:sticky;top:104px;height:min(74vh,740px);min-height:620px;display:grid;grid-template-columns:1.08fr .92fr;gap:clamp(48px,7vw,112px);align-items:stretch;background:#0a0a0a;z-index:2}.exploded-stage{position:relative;height:100%;min-height:0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);display:flex;flex-direction:column;overflow:hidden;background:#0a0a0a}.exploded-head{height:58px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);font-size:9px;text-transform:uppercase;letter-spacing:.16em;color:#76716b;flex:0 0 auto}.exploded-head strong{font-weight:500;color:#d3cec7}.exploded-scene{position:relative;flex:1;perspective:1500px;perspective-origin:50% 38%;overflow:hidden}.exploded-floor{position:absolute;left:8%;right:8%;bottom:9%;height:1px;background:rgba(255,255,255,.08)}.exploded-floor:before,.exploded-floor:after{content:"";position:absolute;top:-44px;width:1px;height:88px;background:rgba(255,255,255,.05)}.exploded-floor:before{left:0}.exploded-floor:after{right:0}.x-layer{--y:0px;--z:0px;position:absolute;left:13%;width:74%;height:57%;top:19%;padding:18px 20px 16px;background:#0d0d0d;border:1px solid rgba(255,255,255,.12);transform-style:preserve-3d;transform:translate3d(0,var(--y),var(--z)) rotateX(58deg) rotateZ(-6deg);transform-origin:50% 50%;opacity:.28;transition:transform .72s var(--ease),opacity .48s var(--ease),border-color .48s var(--ease),background .48s var(--ease),box-shadow .48s var(--ease);box-shadow:0 18px 55px rgba(0,0,0,.18)}.x-layer>*:not(.x-label){opacity:.16;transition:opacity .5s var(--ease)}.x-layer:before{content:"";position:absolute;left:-1px;top:-1px;width:26%;height:1px;background:var(--red);opacity:0;transition:opacity .4s var(--ease),width .6s var(--ease);pointer-events:none}.x-layer:after{content:"";position:absolute;inset:0;border:1px solid rgba(255,255,255,.025);transform:translate3d(8px,8px,-1px);pointer-events:none}.x-layer[data-layer="0"]{--y:-108px;--z:-70px}.x-layer[data-layer="1"]{--y:-38px;--z:-22px}.x-layer[data-layer="2"]{--y:35px;--z:26px}.x-layer[data-layer="3"]{--y:108px;--z:72px}.x-layer .x-label{position:absolute;left:-2px;top:-29px;display:flex;align-items:center;gap:9px;font-size:8px;text-transform:uppercase;letter-spacing:.15em;color:#6f6b65;transform:rotateZ(6deg) rotateX(-58deg);transform-origin:left bottom;white-space:nowrap}.x-layer .x-label b{font-weight:500;color:#817c75}.exploded-stage[data-state="0"] .x-layer[data-layer="0"],.exploded-stage[data-state="1"] .x-layer[data-layer="1"],.exploded-stage[data-state="2"] .x-layer[data-layer="2"],.exploded-stage[data-state="3"] .x-layer[data-layer="3"]{opacity:1;border-color:rgba(255,255,255,.24);background:#101010;box-shadow:0 24px 72px rgba(0,0,0,.36);transform:translate3d(7px,var(--y),calc(var(--z) + 38px)) rotateX(58deg) rotateZ(-6deg) scale(1.012)}.exploded-stage[data-state="0"] .x-layer[data-layer="0"]>*:not(.x-label),.exploded-stage[data-state="1"] .x-layer[data-layer="1"]>*:not(.x-label),.exploded-stage[data-state="2"] .x-layer[data-layer="2"]>*:not(.x-label),.exploded-stage[data-state="3"] .x-layer[data-layer="3"]>*:not(.x-label){opacity:1}.exploded-stage[data-state="0"] .x-layer[data-layer="0"]:before,.exploded-stage[data-state="1"] .x-layer[data-layer="1"]:before,.exploded-stage[data-state="2"] .x-layer[data-layer="2"]:before,.exploded-stage[data-state="3"] .x-layer[data-layer="3"]:before{opacity:1;width:31%}.exploded-stage[data-state="0"] .x-layer[data-layer="0"] .x-label b,.exploded-stage[data-state="1"] .x-layer[data-layer="1"] .x-label b,.exploded-stage[data-state="2"] .x-layer[data-layer="2"] .x-label b,.exploded-stage[data-state="3"] .x-layer[data-layer="3"] .x-label b{color:var(--red)}.structure-wire{height:100%;display:grid;grid-template-columns:1fr 1fr;grid-template-rows:38px 1fr 1fr;gap:10px}.structure-wire i{display:block;border:1px solid rgba(255,255,255,.18)}.structure-wire i:first-child{grid-column:1/3}.structure-wire i:nth-child(2){grid-row:2/4}.structure-wire i:nth-child(3){grid-column:2}.structure-wire i:nth-child(4){grid-column:2}.structure-wire i:before{content:"";display:block;width:34%;height:3px;margin:10px;background:rgba(255,255,255,.22)}.content-proof{height:100%;display:grid;grid-template-columns:1.15fr .85fr;gap:18px}.content-title{font-size:clamp(21px,2vw,34px);line-height:.92;letter-spacing:-.05em;font-weight:520;align-self:start}.content-copy{display:flex;flex-direction:column;gap:8px;padding-top:4px}.content-copy i{height:3px;background:rgba(255,255,255,.17);display:block}.content-copy i:nth-child(2){width:86%}.content-copy i:nth-child(3){width:72%}.content-copy i:nth-child(5){width:62%;margin-top:10px}.link-proof{height:100%;position:relative}.link-proof .link-copy{position:absolute;left:0;right:0;top:12%;font-size:clamp(18px,1.65vw,28px);letter-spacing:-.04em;color:#d8d3cc}.link-proof .anchor{position:absolute;height:1px;background:var(--red);transform-origin:left center;opacity:.82}.link-proof .a1{left:4%;top:50%;width:43%;transform:rotate(-4deg)}.link-proof .a2{left:38%;top:62%;width:44%;transform:rotate(5deg)}.link-proof .a3{left:17%;top:74%;width:58%;transform:rotate(-2deg)}.link-proof .anchor:after{content:"";position:absolute;right:-1px;top:-3px;width:7px;height:7px;border-right:1px solid var(--red);border-top:1px solid var(--red);transform:rotate(45deg)}.tech-proof{height:100%;display:grid;grid-template-columns:repeat(4,1fr);align-items:stretch;border-top:1px solid rgba(255,25