.audit{background:var(--paper);color:var(--ink);padding:clamp(105px,11vw,180px) 0}.audit-head{display:grid;grid-template-columns:.36fr 1.64fr;gap:clamp(38px,7vw,118px);margin-bottom:clamp(56px,7vw,105px)}.audit h2{font-size:clamp(48px,6vw,94px);line-height:.91;letter-spacing:-.061em;font-weight:540;margin:0;max-width:900px}.audit-lead{font-size:clamp(17px,1.25vw,21px);color:#4d4943;margin:30px 0 0;max-width:680px}.audit-board{border-top:1px solid var(--lineD);position:relative}.audit-row{display:grid;grid-template-columns:72px 1.05fr 1.3fr auto;gap:24px;align-items:center;padding:29px 0;border-bottom:1px solid var(--lineD);position:relative;overflow:hidden}.audit-row:before{content:"";position:absolute;left:0;top:0;bottom:0;width:0;background:rgba(232,24,72,.06);transition:width .55s var(--ease)}.audit-row:hover:before{width:100%}.audit-row>*{position:relative;z-index:1}.audit-row .n{font-size:11px;color:#77726b}.audit-row strong{font-size:clamp(24px,2.15vw,35px);font-weight:500;letter-spacing:-.04em}.audit-row p{margin:0;color:#5a5650;max-width:600px}.audit-row i{font-style:normal;font-size:11px;text-transform:uppercase;letter-spacing:.13em;color:var(--red)}
/* Routes */
.routes{background:#0d0d0d;color:#fff;padding:clamp(105px,11vw,178px) 0}.routes-head{display:grid;grid-template-columns:.36fr 1.64fr;gap:clamp(38px,7vw,118px);margin-bottom:clamp(54px,6vw,92px)}.routes h2{font-size:clamp(48px,6vw,92px);line-height:.92;letter-spacing:-.06em;font-weight:530;margin:0}.route-list{border-top:1px solid var(--line)}.route{display:grid;grid-template-columns:72px .75fr 1.05fr .7fr auto;gap:28px;align-items:center;min-height:150px;border-bottom:1px solid var(--line);position:relative;overflow:hidden;transition:padding .4s var(--ease)}.route:before{content:"";position:absolute;left:0;right:0;bottom:0;height:0;background:rgba(255,255,255,.035);transition:height .45s var(--ease)}.route:hover:before{height:100%}.route>*{position:relative;z-index:1}.route .num{font-size:11px;color:#706c66}.route h3{font-size:clamp(30px,3vw,48px);font-weight:500;letter-spacing:-.05em;margin:0}.route p{color:#aaa59e;margin:0;max-width:520px}.micro{height:62px;position:relative;min-width:180px}.micro.tech:before{content:"/seo/technisches-seo";position:absolute;top:21px;left:0;font-size:10px;color:#77726b;letter-spacing:.04em}.micro.tech:after{content:"";position:absolute;left:0;right:0;bottom:14px;height:1px;background:linear-gradient(90deg,var(--red) 0 31%,rgba(255,255,255,.15) 31%)}.micro.local{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.micro.local span{border:1px solid rgba(255,255,255,.17);padding:7px 9px;font-size:9px;text-transform:uppercase;letter-spacing:.1em}.micro.relaunch:before{content:"ALT";position:absolute;left:0;top:20px;font-size:9px;color:#777}.micro.relaunch:after{content:"NEU  ↗";position:absolute;right:0;top:20px;font-size:9px;color:var(--red);letter-spacing:.12em}.micro.relaunch i{position:absolute;left:34px;right:48px;top:29px;height:1px;background:linear-gradient(90deg,#666,var(--red))}.route-arrow{font-size:22px;transition:transform .3s var(--ease)}.route:hover .route-arrow{transform:translate(4px,-4px)}
/* Long-term */
